"use strict";(self.webpackChunkvuepress_theme_reco_demo=self.webpackChunkvuepress_theme_reco_demo||[]).push([[6857],{4326:(s,n,e)=>{e.r(n),e.d(n,{comp:()=>i,data:()=>c});var a=e(641);const l={},i=(0,e(6262).A)(l,[["render",function(s,n){return(0,a.uX)(),(0,a.CE)("div",null,n[0]||(n[0]=[(0,a.Fv)('<blockquote><p>在前端进行的加解密只是过家家，防君子不防小人</p></blockquote><h3 id="前言" tabindex="-1"><a class="header-anchor" href="#前言"><span>前言</span></a></h3><p>在公司中台系统中，对于一些数据内容需要存储在浏览器中，但是直接明文存入觉得不太合适，于是有了这个一般的加解密功能，小小障眼法。</p><h3 id="简介" tabindex="-1"><a class="header-anchor" href="#简介"><span>简介</span></a></h3><p>加密模式：AES-128-CBC</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text" data-title="text"><pre><code><span class="line">import CryptoJS from &#39;crypto-js&#39;;</span>\n<span class="line"></span>\n<span class="line">/**</span>\n<span class="line"> * 生成密钥</span>\n<span class="line"> * @param {number} length - 字符串长度，默认16</span>\n<span class="line"> * @returns {string} 随机字符串</span>\n<span class="line"> */</span>\n<span class="line">export function generateRandomKey(length = 16) {</span>\n<span class="line">  // 可选的字符集（包含大小写字母和数字）</span>\n<span class="line">  const chars = &#39;ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789&#39;;</span>\n<span class="line">  let key = &#39;&#39;;</span>\n<span class="line">  // 确保length是有效数字</span>\n<span class="line">  const len = Number(length) || 16;</span>\n<span class="line">  for (let i = 0; i &lt; len; i++) {</span>\n<span class="line">    key += chars.charAt(Math.floor(Math.random() * chars.length));</span>\n<span class="line">  }</span>\n<span class="line">  </span>\n<span class="line">  return key;</span>\n<span class="line">}</span>\n<span class="line">/**</span>\n<span class="line"> * 对message进行加密</span>\n<span class="line"> */</span>\n<span class="line">export const encryptWithStr = (message, aesKey) =&gt; {</span>\n<span class="line">  return CryptoJS.AES.encrypt(message, aesKey).toString();</span>\n<span class="line">}</span>\n<span class="line">/**</span>\n<span class="line"> * 对message进行解密</span>\n<span class="line"> */</span>\n<span class="line">export const decryptWithStr = (message, aesKey) =&gt; {</span>\n<span class="line">  const bytes = CryptoJS.AES.decrypt(message, aesKey);</span>\n<span class="line">  return bytes.toString(CryptoJS.enc.Utf8);</span>\n<span class="line">}</span>\n<span class="line"></span>\n<span class="line"></span>\n<span class="line"></span>\n<span class="line">// 使用示例</span>\n<span class="line">const message = &quot;需要加密的秘密信息&quot;;</span>\n<span class="line">const aesKey = generateRandomKey(); // 生成16位密钥</span>\n<span class="line"></span>\n<span class="line">console.log(&quot;生成的密钥:&quot;, aesKey);</span>\n<span class="line">console.log(&quot;密钥长度:&quot;, aesKey.length);</span>\n<span class="line"></span>\n<span class="line">const encrypted = encryptWithStr(message, aesKey);</span>\n<span class="line">console.log(&quot;加密结果:&quot;, encrypted);</span>\n<span class="line"></span>\n<span class="line">const decrypted = decryptWithStr(encrypted, aesKey);</span>\n<span class="line">console.log(&quot;解密结果:&quot;, decrypted);</span>\n<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="一些提醒" tabindex="-1"><a class="header-anchor" href="#一些提醒"><span>一些提醒</span></a></h3><ol><li><strong>密钥保存</strong>：生成的密钥需要安全保存，密钥丢失则无法解密</li><li><strong>密钥共享</strong>：如果需要多个地方解密，需要安全地共享这个密钥</li></ol>',8)]))}]]),c=JSON.parse('{"path":"/blogs/javascript/encrypt_decrypt.html","title":"前端加密与解密","lang":"zh-CN","frontmatter":{"title":"前端加密与解密","date":"2025/11/06","tags":["FE","JavaScript"],"categories":["JavaScript"]},"headers":[{"level":3,"title":"前言","slug":"前言","link":"#前言","children":[]},{"level":3,"title":"简介","slug":"简介","link":"#简介","children":[]},{"level":3,"title":"一些提醒","slug":"一些提醒","link":"#一些提醒","children":[]}],"git":{"createdTime":1765011168000,"updatedTime":1765011168000,"contributors":[{"name":"Lirioing","email":"lirong@xgw66.com","commits":1}]},"filePathRelative":"blogs/javascript/encrypt&decrypt.md"}')}}]);